const profileById = new Map(profiles.map((profile) => [profile.id, profile]));

const sources: Source[] = recipes.map(({id, sourceTitle, url, author, book}) => ({
  id:'batch-i-' + id,title:sourceTitle,url,author,book,checkedAt,
}));

const versions: RecipeVersion[] = recipes.map((recipe) => {
  const profile = profileById.get(recipe.id);
  if (!profile) throw new Error('Missing Batch I profile: ' + recipe.id);
  return {
    id:recipe.id + '-batch-i',cocktailId:recipe.id,label:sourceLabel(recipe.publisher),sourceId:'batch-i-' + recipe.id,
    servings:1,ingredients:recipe.ingredients,steps:recipe.steps,originalLanguage:'en',originalSteps:recipe.originalSteps,
    glass:recipe.glass,garnish:recipe.garnish,flavours:profile.flavours,tastes:profile.tastes,strength:profile.strength,
    approachability:profile.approachability,profileBasis:'editorial',profileNote:editorial(profile),sourceChecked:true,translationStatus:'draft',
  };
});

const curatedIds = new Set([
  'breakfast-martini', 'division-bell', 'oaxaca-old-fashioned', 'gin-gin-mule',
  'mezcal-mule', 'tequila-mockingbird', 'bourbon-renewal', 'brown-butter-old-fashioned',
  'irish-old-fashioned', 'st-germain-cocktail', 'hugo-spritz',
]);

const cocktails: Cocktail[] = profiles.map((profile) => ({
  id:profile.id,name:profile.name,aliases:profile.aliases ?? [],category:curatedIds.has(profile.id) ? 'curated' : 'classic',description:profile.description,
  versionIds:[profile.id + '-batch-i'],defaultVersionId:profile.id + '-batch-i',accent:profile.accent,
}));

export const batchI: CatalogueBatch = {cocktails,versions,sources,ingredients,brands};
export default batchI;
